"use client";

import { useState } from 'react';
import { Sidebar } from '@/components/sidebar';
import { useAppStore } from '@/lib/store';
import { ArrowLeft } from 'lucide-react';
import { useParams, useRouter } from 'next/navigation';
import Link from 'next/link';
import { MediaRenderer } from '@/components/media-renderer';

export default function ComicReaderPage() {
  const params = useParams();
  const categoryParam = params.category as string;
  const idParam = params.id as string;
  const { comics, categories } = useAppStore();

  const item = comics.find(c => c.id === idParam);
  let defaultLabel = '연재 만화';
  if (categoryParam === 'fantasy') defaultLabel = '판타지';
  
  const currentCategoryObj = categories.find(c => c.id === categoryParam);
  const categoryTitle = currentCategoryObj ? currentCategoryObj.label : defaultLabel;

  if (!item) {
    return (
      <div className="min-h-screen bg-background">
        <Sidebar />
        <main className="min-h-screen pt-16 lg:pt-0 max-w-6xl mx-auto px-6 py-12 flex justify-center items-center">
          <p>작품을 찾을 수 없습니다.</p>
        </main>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#0f0f0f] text-white">
      <Sidebar />
      <main className="min-h-screen pt-16 lg:pt-0">
        <div className="max-w-3xl mx-auto">
          {/* Header */}
          <div className="sticky top-16 lg:top-0 z-40 bg-[#1a1a1a]/95 backdrop-blur border-b border-white/10 px-4 py-4 flex items-center justify-between">
            <Link href={"/comics/short/" + categoryParam} className="inline-flex items-center text-sm font-medium text-gray-300 hover:text-white transition-colors">
              <ArrowLeft className="mr-2 h-5 w-5" />
              {categoryTitle}
            </Link>
            <h1 className="text-lg font-bold truncate max-w-[200px] sm:max-w-sm">{item.title}</h1>
            <div className="w-6" /> {/* Placeholder for balance */}
          </div>
          
          {/* Viewer */}
          <div className="flex flex-col items-center bg-black min-h-[80vh]">
            <MediaRenderer images={item.images} htmlLogs={item.htmlLogs} />
          </div>

          {/* Footer */}
          <div className="bg-[#1a1a1a] p-6 text-center border-t border-white/10">
             <p className="text-gray-400 text-sm mb-4">작품의 마지막입니다.</p>
             <Link href={"/comics/short/" + categoryParam}>
               <button className="bg-white text-black px-6 py-2 rounded-full font-bold hover:bg-gray-200 transition">
                 목록으로 돌아가기
               </button>
             </Link>
          </div>
        </div>
      </main>
    </div>
  );
}

